var splitArray = function(nums, k) {
    let low = Math.max(...nums);
    let high = nums.reduce((a, b) => a + b, 0);

    const partsNeeded = (limit) => {
        let parts = 1, current = 0;
        for (const value of nums) {
            if (current + value > limit) {
                parts += 1;
                current = value;
            } else {
                current += value;
            }
        }
        return parts;
    };

    while (low < high) {
        const middle = Math.floor((low + high) / 2);
        if (partsNeeded(middle) <= k) {
            high = middle;
        } else {
            low = middle + 1;
        }
    }

    return low;
};

solution.python:
from typing import List

class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        low, high = max(nums), sum(nums)

        def parts_needed(limit: int) -> int:
            parts = 1
            current = 0
            for value in nums:
                if current + value > limit:
                    parts += 1
                    current = value
                else:
                    current += value
            return parts

        while low < high:
            middle = (low + high) // 2
            if parts_needed(middle) <= k:
                high = middle
            else:
                low = middle + 1

        return low
